project_task.solution:
def move(pos, direction):
    x, y = pos
    if direction == "kuzey":
        y += 1
    elif direction == "güney":
        y -= 1
    elif direction == "doğu":
        x += 1
    elif direction == "batı":
        x -= 1
    return (x, y)

print(move((0, 0), "kuzey"))

