project_task.solution:
def clean(message):
    return message.strip().lower()


def get_reply(message, bot_name="Bilge"):
    text = clean(message)
    if "merhaba" in text:
        return f"Merhaba, ben {bot_name}!"
    elif "hava" in text:
        return "Bugün hava güneşli."
    else:
        return "Bunu anlamadım."

